<script setup lang="ts">
import {ref,onMounted,onUnmounted,nextTick} from 'vue';
import {RouterLink} from 'vue-router';
import axios from 'axios';
import MarkdownIt from 'markdown-it';
const markdown=new MarkdownIt({html:false,linkify:false,breaks:true}).disable(['image']);
markdown.renderer.rules.link_open=(tokens,idx)=>{const href=String(tokens[idx]!.attrGet('href')||'');let allowed=false;try{const u=new URL(href,window.location.origin);allowed=(u.origin===window.location.origin&&/^\/(campus|market|lost-found|notifications)([/?]|$)/.test(u.pathname))||(u.protocol==='https:'&&u.hostname.endsWith('.sdu.edu.cn'));}catch{}return allowed?'<a href="'+markdown.utils.escapeHtml(href)+'" target="_blank" rel="noopener noreferrer">':'<a>';};
interface Source{number:number;title:string;url:string;campus:string;fetchedAt:string;excerpt:string}
interface Card{title:string;subtitle:string;url:string;imageUrl:string}
interface Message{role:string;content:string;metadata?:{sources?:Source[];cards?:Card[];interrupted?:boolean}}
const historyLoading=ref(false);
const open=ref(false),hidden=ref(false),dragging=ref(false),playful=ref(false);
const x=ref(0),y=ref(0),question=ref(''),busy=ref(false),step=ref(''),error=ref('');
const messages=ref<Message[]>([]),conversations=ref<{id:string;title:string}[]>([]),conversationId=ref('');
const transcript=ref<HTMLElement|null>(null),input=ref<HTMLTextAreaElement|null>(null),status=ref<any>(null);
let reaction:ReturnType<typeof setTimeout>|undefined,controller:AbortController|undefined,dragStart={x:0,y:0,left:0,top:0},moved=false,historyRequest=0,destroyed=false;

function clamp(){x.value=Math.max(0,Math.min(window.innerWidth-114,x.value));y.value=Math.max(110,Math.min(window.innerHeight-152,y.value));}
function down(e:PointerEvent){if(e.button!==0)return;dragging.value=true;moved=false;dragStart={x:e.clientX,y:e.clientY,left:x.value,top:y.value};(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);}
function move(e:PointerEvent){if(!dragging.value)return;const dx=e.clientX-dragStart.x,dy=e.clientY-dragStart.y;if(Math.hypot(dx,dy)>6)moved=true;if(moved){x.value=dragStart.left+dx;y.value=dragStart.top+dy;clamp();}}
function up(){if(!dragging.value)return;dragging.value=false;playful.value=true;clearTimeout(reaction);reaction=setTimeout(()=>playful.value=false,900);}
function click(){if(moved){moved=false;return;}toggle();}
async function toggle(){open.value=!open.value;if(open.value){await loadList();await loadStatus();await scroll();input.value?.focus();}}
async function loadStatus(){try{status.value=(await axios.get('/api/assistant/status')).data;}catch{}}
async function loadList(){try{conversations.value=(await axios.get('/api/assistant/conversations')).data;}catch{error.value='对话列表加载失败，请重试';}}
async function scroll(){await nextTick();if(transcript.value)transcript.value.scrollTop=transcript.value.scrollHeight;}
async function changeConversation(){if(busy.value)return;const n=++historyRequest;error.value='';messages.value=[];if(!conversationId.value)return;historyLoading.value=true;try{const {data}=await axios.get('/api/assistant/conversations/'+conversationId.value);if(n===historyRequest){messages.value=data;await scroll();}}catch{if(n===historyRequest)error.value='对话加载失败';}finally{if(n===historyRequest)historyLoading.value=false;}}
function fresh(){if(busy.value)return;historyRequest++;historyLoading.value=false;conversationId.value='';messages.value=[];question.value='';error.value='';input.value?.focus();}
function safeSource(url:string){try{const u=new URL(url);return u.protocol==='https:'&&u.hostname.endsWith('.sdu.edu.cn')?url:undefined;}catch{return undefined;}}
function safeCard(url:string){return /^\/(market\/\d+|lost-found\/\d+|campus\?place=\d+|notifications)$/.test(url)?url:'/';}
async function send(text?:string){
 if(busy.value||historyLoading.value)return;if(text)question.value=text;const q=question.value.trim();if(!q)return;
 busy.value=true;error.value='';step.value='正在连接校园助手…';controller=new AbortController();let accepted=false,pushed=false;
 try{
  const headers={'X-XSRF-TOKEN':(await axios.get('/api/auth/csrf')).data.token,'Content-Type':'application/json'};
  if(!conversationId.value)conversationId.value=(await axios.post('/api/assistant/conversations',null,{headers})).data.id;
  messages.value.push({role:'user',content:q});const reply:Message={role:'assistant',content:'',metadata:{sources:[],cards:[]}};messages.value.push(reply);pushed=true;const index=messages.value.length-1;question.value='';await scroll();
  const response=await fetch('/api/assistant/ask',{method:'POST',credentials:'same-origin',headers,signal:controller.signal,body:JSON.stringify({conversationId:conversationId.value,question:q})});
  if(!response.ok){throw new Error(response.status===429?'助手正在忙碌，请稍后再试':response.status===503?'校园助手尚未配置好，请稍后再试':'请求失败，请检查登录状态后重试');}
  accepted=true;if(!response.body)throw new Error('浏览器不支持流式响应');
  const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',doneEvent=false;
  function frame(block:string){let name='',data='';for(const line of block.split('\n')){if(line.startsWith('event:'))name=line.slice(6).trim();if(line.startsWith('data:'))data+=line.slice(5).trim();}if(!data)return;const value=JSON.parse(data);const m=messages.value[index];if(!m)return;
   if(name==='step')step.value=value.text;
   else if(name==='token'){m.content+=value.text;scroll();}
   else if(name==='sources')m.metadata!.sources=value;
   else if(name==='cards')m.metadata!.cards=value;
   else if(name==='error')error.value=value.message;
   else if(name==='done')doneEvent=true;
  }
  while(true){const {done,value}=await reader.read();buffer+=decoder.decode(value,{stream:!done}).replace(/\r\n/g,'\n');let at;while((at=buffer.indexOf('\n\n'))>=0){frame(buffer.slice(0,at));buffer=buffer.slice(at+2);}if(done)break;}
  if(buffer.trim())frame(buffer);if(!doneEvent&&!error.value)error.value='回答已中断，已保留的内容可在历史对话中查看';
 }catch(e){if(!accepted&&pushed){messages.value.splice(-2,2);question.value=q;}if(!destroyed){error.value=e instanceof Error&&e.name==='AbortError'?'已停止回答':e instanceof Error?e.message:'连接失败，请重试';}}
 finally{busy.value=false;step.value='';controller=undefined;if(!destroyed){await loadList();await loadStatus();await scroll();}}
}
async function stop(){controller?.abort();try{const token=(await axios.get('/api/auth/csrf')).data.token;await axios.post('/api/assistant/cancel',null,{headers:{'X-XSRF-TOKEN':token}});}catch{}}
function key(e:KeyboardEvent){if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send();}}
onMounted(()=>{x.value=window.innerWidth-140;y.value=window.innerHeight-180;clamp();window.addEventListener('resize',clamp);});
onUnmounted(()=>{destroyed=true;controller?.abort();clearTimeout(reaction);window.removeEventListener('resize',clamp);});
</script>

<template>
 <Teleport to="body">
  <button v-if="hidden" class="sea-restore" @click="hidden=false" aria-label="唤醒汐月校园助手">☾<span>汐月</span></button>
  <div v-else class="sea-pet" :class="{dragging,resting:open}" :style="{left:x+'px',top:y+'px'}">
   <span v-if="!open" class="pet-whisper">校园问题，问汐月</span>
   <button class="pet-character" aria-label="汐月校园助手，点击聊天或拖动移动" @pointerdown="down" @pointermove="move" @pointerup="up" @pointercancel="up" @click="click" :class="{playful}">
    <span class="pet-sprite" role="img" aria-label="海棠与海鸥装饰的小海妖汐月"></span><i class="spark a">✧</i><i class="spark b">✦</i>
   </button>
   <button class="pet-hide" @click="hidden=true;open=false" aria-label="收起海妖助手">−</button>
  </div>
  <section v-if="open" class="sea-chat" role="dialog" aria-modal="false" aria-labelledby="sea-title" @keydown.esc="open=false">
   <header class="sea-header"><img src="/assets/assistant/sea-sprite-v2.png" alt=""><div><small>SDU · CAMPUS COMPANION</small><h2 id="sea-title">汐月 <span>你的校园小海妖</span></h2></div><button @click="open=false" aria-label="关闭问答弹窗">×</button></header>
   <div class="sea-toolbar"><select v-model="conversationId" @change="changeConversation" :disabled="busy" aria-label="选择历史对话"><option value="">新的校园对话</option><option v-for="c in conversations" :value="c.id" :key="c.id">{{c.title}}</option></select><button :disabled="busy" @click="fresh">＋ 新对话</button></div>
   <div ref="transcript" class="sea-transcript" aria-live="polite" aria-relevant="additions text">
    <div v-if="!messages.length" class="sea-welcome"><span>☾</span><h3>你好呀，我是汐月。</h3><p>陪你找校园里的答案，也帮你找好物、找失物。<br>官方资料有出处，不确定的事情会告诉你。</p><div><button @click="send('山大本科生图书可以借多久？')" :disabled="busy">📖 借书可以借多久？</button><button @click="send('校园网总是需要重新认证怎么办？')" :disabled="busy">🌐 校园网连接问题</button><button @click="send('帮我找找有没有拾到钥匙的招领信息')" :disabled="busy">🗝 寻找遗失的钥匙</button></div></div>
    <article v-for="(m,index) in messages" :key="index" class="sea-message" :class="m.role"><img v-if="m.role==='assistant'" class="sea-avatar" src="/assets/assistant/sea-sprite-v2.png" alt="汐月"><div class="message-main"><small>{{m.role==='user'?'我':'汐月'}}</small><div class="sea-text" v-html="markdown.render(m.content|| (busy&&index===messages.length-1?'正在寻找答案…':'这条回答未完成，请重新提问。'))"></div><div v-if="m.metadata?.cards?.length" class="sea-cards"><RouterLink v-for="card in m.metadata.cards" :key="card.url" :to="safeCard(card.url)" @click="open=false"><img v-if="card.imageUrl?.startsWith('/api/')||card.imageUrl?.startsWith('/assets/')" :src="card.imageUrl" alt=""><span><b>{{card.title}}</b><small>{{card.subtitle}}</small></span><span>↗</span></RouterLink></div><details v-if="m.metadata?.sources?.length" class="sea-sources"><summary>参考资料 · {{m.metadata.sources.length}} 个片段</summary><div v-for="source in m.metadata.sources" :key="source.number"><a :href="safeSource(source.url)" target="_blank" rel="noopener noreferrer">[{{source.number}}] {{source.title}} ↗</a><small>{{source.campus}} · 采集于 {{source.fetchedAt}}</small><p>{{source.excerpt}}</p></div></details></div></article>
   </div>
   <p v-if="busy" class="sea-step" role="status"><i></i>{{step}}</p><p v-if="error" class="sea-error" role="alert">{{error}}</p>
   <form class="sea-composer" @submit.prevent="send()"><textarea ref="input" v-model="question" maxlength="2000" rows="2" @keydown="key" :disabled="busy||historyLoading" placeholder="问问汐月校园里的事…" aria-label="输入校园问题"></textarea><button v-if="busy" type="button" @click="stop" class="stop">停止</button><button v-else :disabled="!question.trim()||historyLoading" aria-label="发送问题">↑</button></form>
   <footer class="sea-footnote">Enter 发送 · Shift+Enter 换行 · 重要事项请核对官方通知<span v-if="status?.knowledge">已收录 {{status.knowledge.documents}} 份资料 · {{status.knowledge.syncing?'知识更新中':status.knowledge.retrieval}}</span></footer>
  </section>
 </Teleport>
</template>

