e;font:inherit;font-size:12px;line-height:1.8;color:#395552;background:none;max-height:110px}.sea-composer>button{height:33px;width:33px;border:0;background:#527b73;color:white;font-size:21px;border-radius:10px;flex-shrink:0}.sea-composer>button.stop{width:auto;font-size:11px;padding:0 10px}.sea-chat button:disabled{opacity:.45;cursor:default}.sea-chat>.sea-footnote{margin:0;padding:10px 18px 12px;border:0;display:block;color:#8c9a8e;font-size:9px;letter-spacing:0;line-height:1.8;flex-shrink:0}.sea-footnote>span{display:block;font-size:8px;color:#9aa99b}
